{
  "name": "spriteforge",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "SpriteForge — a browser-based animated pixel-art sprite studio.",
  "scripts": {
    "dev": "vite",
    "build": "tsc --noEmit && vite build",
    "preview": "vite preview",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "gifenc": "^1.0.3"
  },
  "devDependencies": {
    "typescript": "^5.6.3",
    "vite": "^5.4.10",
    "vitest": "^2.1.4"
  }
}

import { defineConfig } from 'vite';

export default defineConfig({
  base: './',
  build: {
    target: 'es2020',
    outDir: 'dist',
    assetsInlineLimit: 100000000,
  },
});

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'node',
    include: ['src/**/*.test.ts'],
    globals: false,
  },
});

declare module 'gifenc' {
  export type Palette = number[][];
  export interface QuantizeOptions {
    format?: 'rgb565' | 'rgb444' | 'rgba4444';
    oneBitAlpha?: boolean | number;
    clearAlpha?: boolean;
    clearAlphaThreshold?: number;
    clearAlphaColor?: number;
  }
  export interface WriteFrameOptions {
    palette: Palette;
    delay?: number;
    repeat?: number;
    transparent?: boolean;
    transparentIndex?: number;
    first?: boolean;
  }
  export interface Encoder {
    writeFrame(index: Uint8Array, width: number, height: number, opts?: WriteFrameOptions): void;
    finish(): void;
    bytes(): Uint8Array;
    bytesView(): Uint8Array;
    reset(): void;
  }
  export function GIFEncoder(opts?: { auto?: boolean; initialCapacity?: number }): Encoder;
  export function quantize(rgba: Uint8Array | Uint8ClampedArray, maxColors: number, options?: QuantizeOptions): Palette;
  export function applyPalette(
    rgba: Uint8Array | Uint8ClampedArray,
    palette: Palette,
    format?: 'rgb565' | 'rgb444' | 'rgba4444'
  ): Uint8Array;
  export function nearestColorIndex(palette: Palette, pixel: number[]): number;
  export function nearestColor(palette: Palette, pixel: number[]): number[];
  const _default: unknown;
  export default _default;
}

// Core, serializable document model for SpriteForge.
// All pixel data is palette-indexed: a cel is an Int-length array of numbers
// where -1 means "transparent" and any value >= 0 indexes into the palette.

export type ToolId = 'pencil' | 'eraser' | 'line' | 'rect' | 'ellipse' | 'fill' | 'picker';

export const CANVAS_SIZE = 32;
export const DISPLAY_SIZE = 512;
export const MAX_FRAMES = 64;
export const MAX_DURATION = 24;
export const MAX_FPS = 24;

/** A layer's metadata (pixel data lives on the frame cels, indexed by layer). */
export interface LayerState {
  id: string;
  name: string;
  visible: boolean;
  /** 0..100 percent, applied as alpha during compositing. */
  opacity: number;
}

/** A single frame: a hold duration plus one cel per layer (aligned to DocState.layers). */
export interface FrameState {
  /** 1..MAX_DURATION units of the playback rate. */
  duration: number;
  /** cels[layerIndex] has length width*height; entries are -1 or a palette index. */
  cels: number[][];
}

/** The full editable, serializable document state (the "model"). */
export interface DocState {
  width: number;
  height: number;
  /** Palette colors as "#rrggbb". Index 0 is never the eraser; transparency is -1. */
  palette: string[];
  /** Index into palette for the currently selected drawing color. */
  activeColor: number;
  /** Draw order: index 0 is the bottom layer, the last entry is on top. */
  layers: LayerState[];
  frames: FrameState[];
  activeFrame: number;
  /** Index into layers for the active drawing target. */
  activeLayer: number;
  /** 1..MAX_FPS. */
  fps: number;
  loop: boolean;
  onionSkin: boolean;
  /** 0..100 percent opacity for the onion-skin ghost of the previous frame. */
  onionOpacity: number;
  tool: ToolId;
  /** 1 or 2 pixels. */
  brushSize: number;
}

export const DEFAULT_PALETTE: string[] = [
  '#000000',
  '#1f1f1f',
  '#5a5a5a',
  '#9a9a9a',
  '#ffffff',
  '#e43b44',
  '#287f79',
  '#8d6f47',
  '#7f80f4',
  '#e3b5a3',
  '#c4524b',
  '#689e86',
  '#a7a7a7',
  '#6f98bd',
  '#d9d9d9',
  '#c4b39b',
];

export interface PalettePreset {
  name: string;
  colors: string[];
}

export const PALETTE_PRESETS: PalettePreset[] = [
  { name: 'Default 16', colors: DEFAULT_PALETTE.slice() },
  {
    name: 'Gameboy',
    colors: ['#0f380f', '#306230', '#8bac0f', '#9bbc0f'],
  },
  {
    name: 'Sweetie 16',
    colors: [
      '#1a1c2c',
      '#5d275d',
      '#b13e53',
      '#ef7d57',
      '#ffcd75',
      '#a7f070',
      '#38b764',
      '#257179',
      '#29366f',
      '#3b5dc9',
      '#41a6f6',
      '#73eff7',
      '#f4f4f4',
      '#94b0c2',
      '#566c86',
      '#333c57',
    ],
  },
];

export const MAX_LAYERS = 32;

let idCounter = 0;
/** Collision-resistant enough for a single-user local session. */
export function makeLayerId(): string {
  idCounter += 1;
  return `layer-${Date.now().toString(36)}-${idCounter.toString(36)}`;
}

export function emptyCel(width: number, height: number): number[] {
  return new Array<number>(width * height).fill(-1);
}

export function createLayer(name: string): LayerState {
  return { id: makeLayerId(), name, visible: true, opacity: 100 };
}

/** A fresh document with the default palette and four layers / one frame. */
export function createInitialState(): DocState {
  const width = CANVAS_SIZE;
  const height = CANVAS_SIZE;
  const layerNames = ['Background', 'Character', 'Props', 'FX'];
  const layers: LayerState[] = layerNames.map((name) => createLayer(name));
  const cels = layers.map((_, i) => {
    const cel = emptyCel(width, height);
    // Give the bottom layer a soft checker-ish backdrop-free default of transparency.
    if (i === 0) {
      /* leave transparent on purpose */
    }
    return cel;
  });
  return {
    width,
    height,
    palette: DEFAULT_PALETTE.slice(),
    activeColor: 0,
    layers,
    frames: [{ duration: 4, cels }],
    activeFrame: 0,
    activeLayer: 0,
    fps: 8,
    loop: true,
    onionSkin: false,
    onionOpacity: 30,
    tool: 'pencil',
    brushSize: 1,
  };
}

// Pure geometry helpers for the drawing tools. All functions operate on
// integer grid coordinates and return arrays of [x, y] pairs; callers are
// responsible for clamping/validating against the canvas bounds.

export type Point = [number, number];

function inBounds(w: number, h: number, x: number, y: number): boolean {
  return x >= 0 && y >= 0 && x < w && y < h;
}

/** Bresenham line from (x0,y0) to (x1,y1), inclusive of both endpoints. */
export function linePoints(x0: number, y0: number, x1: number, y1: number): Point[] {
  const pts: Point[] = [];
  let dx = Math.abs(x1 - x0);
  let dy = -Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1;
  const sy = y0 < y1 ? 1 : -1;
  let err = dx + dy;
  let x = x0;
  let y = y0;
  // Guard against pathological loops; the loop is bounded by the box size.
  for (;;) {
    pts.push([x, y]);
    if (x === x1 && y === y1) break;
    const e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      x += sx;
    }
    if (e2 <= dx) {
      err += dx;
      y += sy;
    }
  }
  return pts;
}

/** Rectangle outline between two opposite corners (filled when fill=true). */
export function rectPoints(x0: number, y0: number, x1: number, y1: number, fill = false): Point[] {
  const xa = Math.min(x0, x1);
  const xb = Math.max(x0, x1);
  const ya = Math.min(y0, y1);
  const yb = Math.max(y0, y1);
  const pts: Point[] = [];
  for (let x = xa; x <= xb; x++) {
    pts.push([x, ya]);
    if (yb !== ya) pts.push([x, yb]);
  }
  for (let y = ya + 1; y < yb; y++) {
    pts.push([xa, y]);
    if (xb !== xa) pts.push([xb, y]);
  }
  if (fill) {
    const out: Point[] = [];
    for (let y = ya; y <= yb; y++) for (let x = xa; x <= xb; x++) out.push([x, y]);
    return out;
  }
  return pts;
}

/**
 * Ellipse outline inscribed in the bounding box defined by two opposite
 * corners, using the midpoint ellipse algorithm (mirrored into 4 quadrants).
 */
export function ellipsePoints(x0: number, y0: number, x1: number, y1: number, fill = false): Point[] {
  const xa = Math.min(x0, x1);
  const xb = Math.max(x0, x1);
  const ya = Math.min(y0, y1);
  const yb = Math.max(y0, y1);
  const w = xb - xa + 1;
  const h = yb - ya + 1;
  const cx = xa + (w - 1) / 2;
  const cy = ya + (h - 1) / 2;
  const rx = (w - 1) / 2;
  const ry = (h - 1) / 2;
  const pts: Point[] = [];
  const seen = new Set<number>();
  const push = (x: number, y: number) => {
    const rx0 = Math.round(x);
    const ry0 = Math.round(y);
    const key = ry0 * 4096 + rx0;
    if (!seen.has(key)) {
      seen.add(key);
      pts.push([rx0, ry0]);
    }
  };

  if (rx === 0 && ry === 0) return [[xa, ya]];

  // Sample by parameter to keep the outline connected for small radii.
  const steps = Math.max(8, Math.ceil(Math.PI * (rx + ry) * 2));
  for (let i = 0; i < steps; i++) {
    const t = (i / steps) * Math.PI * 2;
    push(cx + rx * Math.cos(t), cy + ry * Math.sin(t));
  }

  if (fill) {
    const out: Point[] = [];
    for (let y = ya; y <= yb; y++) {
      for (let x = xa; x <= xb; x++) {
        const nx = rx === 0 ? 0 : (x - cx) / rx;
        const ny = ry === 0 ? 0 : (y - cy) / ry;
        if (nx * nx + ny * ny <= 1.05) out.push([x, y]);
      }
    }
    return out;
  }
  return pts;
}

/**
 * 4-connected flood fill. Returns the set of coordinates that should change,
 * stopping at pixels whose value differs from the seed value. Operates purely
 * on a cel array; does not mutate it.
 */
export function floodFill(
  cel: number[],
  width: number,
  height: number,
  sx: number,
  sy: number,
  targetIndex: number,
  replacementIndex: number
): Point[] {
  if (!inBounds(width, height, sx, sy)) return [];
  const seed = sy * width + sx;
  if (cel[seed] === replacementIndex) return [];
  const result: Point[] = [];
  const stack: number[] = [seed];
  const visited = new Set<number>();
  while (stack.length) {
    const p = stack.pop()!;
    if (visited.has(p)) continue;
    visited.add(p);
    if (cel[p] !== targetIndex) continue;
    const x = p % width;
    const y = (p - x) / width;
    result.push([x, y]);
    if (x > 0) stack.push(p - 1);
    if (x < width - 1) stack.push(p + 1);
    if (y > 0) stack.push(p - width);
    if (y < height - 1) stack.push(p + width);
  }
  return result;
}

/** A rectangular brush footprint anchored at (x,y) for the given size. */
export function brushPoints(x: number, y: number, size: number, width: number, height: number): Point[] {
  const pts: Point[] = [];
  for (let dy = 0; dy < size; dy++) {
    for (let dx = 0; dx < size; dx++) {
      const px = x + dx;
      const py = y + dy;
      if (inBounds(width, height, px, py)) pts.push([px, py]);
    }
  }
  return pts;
}

/** Points along a straight segment using the brush (for drag drawing between events). */
export function brushStroke(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  size: number,
  width: number,
  height: number
): Point[] {
  const seen = new Set<number>();
  const out: Point[] = [];
  for (const [x, y] of linePoints(x0, y0, x1, y1)) {
    for (const [bx, by] of brushPoints(x, y, size, width, height)) {
      const key = by * width + bx;
      if (!seen.has(key)) {
        seen.add(key);
        out.push([bx, by]);
      }
    }
  }
  return out;
}

// Pure compositing: turns a DocState's frame into an RGBA8 buffer by
// source-over blending the visible layers (bottom to top) with per-layer alpha.

import type { DocState } from './types';
import { hexToRgb } from './color';

export interface RGBA {
  width: number;
  height: number;
  data: Uint8ClampedArray; // length width*height*4
}

export function blankRGBA(width: number, height: number): RGBA {
  return { width, height, data: new Uint8ClampedArray(width * height * 4) };
}

/**
 * Composite a single frame into RGBA. Layers are blended bottom-to-top; a
 * hidden layer contributes nothing and a layer's opacity acts as its pixel
 * alpha (drawn pixels are treated as opaque colors modulated by opacity).
 */
export function compositeFrame(doc: DocState, frameIndex: number): RGBA {
  const { width, height } = doc;
  const out = blankRGBA(width, height);
  const frame = doc.frames[frameIndex];
  if (!frame) return out;

  // Pre-decode palette to rgb triples once.
  const pal = doc.palette.map(hexToRgb);

  for (let li = 0; li < doc.layers.length; li++) {
    const layer = doc.layers[li];
    if (!layer.visible || layer.opacity <= 0) continue;
    const cel = frame.cels[li];
    if (!cel) continue;
    const srcA = layer.opacity / 100;
    for (let p = 0; p < width * height; p++) {
      const idx = cel[p];
      if (idx < 0) continue; // transparent
      const c = pal[idx];
      if (!c) continue;
      const o = p * 4;
      // Source is the palette color at alpha = srcA; destination is current.
      const dstA = out.data[o + 3] / 255;
      const outA = srcA + dstA * (1 - srcA);
      if (outA <= 0) continue;
      const inv = 1 - srcA;
      out.data[o + 0] = (c[0] * srcA + out.data[o + 0] * dstA * inv) / outA;
      out.data[o + 1] = (c[1] * srcA + out.data[o + 1] * dstA * inv) / outA;
      out.data[o + 2] = (c[2] * srcA + out.data[o + 2] * dstA * inv) / outA;
      out.data[o + 3] = outA * 255;
    }
  }
  return out;
}

/**
 * Composite every layer except the active one, for use as a preview base while
 * a shape tool is being dragged (the shape itself is drawn on top in the UI).
 */
export function compositeExceptLayer(doc: DocState, frameIndex: number, skipLayer: number): RGBA {
  const { width, height } = doc;
  const out = blankRGBA(width, height);
  const frame = doc.frames[frameIndex];
  if (!frame) return out;
  const pal = doc.palette.map(hexToRgb);
  for (let li = 0; li < doc.layers.length; li++) {
    if (li === skipLayer) continue;
    const layer = doc.layers[li];
    if (!layer.visible || layer.opacity <= 0) continue;
    const cel = frame.cels[li];
    if (!cel) continue;
    const srcA = layer.opacity / 100;
    for (let p = 0; p < width * height; p++) {
      const idx = cel[p];
      if (idx < 0) continue;
      const c = pal[idx];
      if (!c) continue;
      const o = p * 4;
      const dstA = out.data[o + 3] / 255;
      const outA = srcA + dstA * (1 - srcA);
      if (outA <= 0) continue;
      const inv = 1 - srcA;
      out.data[o + 0] = (c[0] * srcA + out.data[o + 0] * dstA * inv) / outA;
      out.data[o + 1] = (c[1] * srcA + out.data[o + 1] * dstA * inv) / outA;
      out.data[o + 2] = (c[2] * srcA + out.data[o + 2] * dstA * inv) / outA;
      out.data[o + 3] = outA * 255;
    }
  }
  return out;
}

/**
 * Composite a frame to a checkerboard background (for the editor canvas),
 * so transparent pixels read as "empty" rather than black.
 */
export function compositeOnChecker(doc: DocState, frameIndex: number): RGBA {
  const { width, height } = doc;
  const base = compositeFrame(doc, frameIndex);
  const out = blankRGBA(width, height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const p = (y * width + x) * 4;
      const light = (x + y) % 2 === 0 ? 204 : 168;
      const a = base.data[p + 3] / 255;
      const inv = 1 - a;
      out.data[p + 0] = base.data[p + 0] * a + light * inv;
      out.data[p + 1] = base.data[p + 1] * a + light * inv;
      out.data[p + 2] = base.data[p + 2] * a + light * inv;
      out.data[p + 3] = 255;
    }
  }
  return out;
}

// Color utilities: hex parsing/formatting and nearest-color math used by the
// import quantizer and the GIF encoder. Pure, no DOM.

export interface RGB {
  r: number;
  g: number;
  b: number;
}

const HEX = /^#?([0-9a-fA-F]{6})$/;

/** Parses "#rrggbb" (with or without '#'); throws on malformed input. */
export function parseHex(hex: string): RGB {
  const m = HEX.exec(hex.trim());
  if (!m) throw new Error(`Invalid hex color: ${hex}`);
  const n = parseInt(m[1], 16);
  return { r: (n >> 16) & 0xff, g: (n >> 8) & 0xff, b: n & 0xff };
}

export function hexToRgb(hex: string): number[] {
  const { r, g, b } = parseHex(hex);
  return [r, g, b];
}

export function rgbToHex(r: number, g: number, b: number): string {
  const c = (v: number) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0');
  return `#${c(r)}${c(g)}${c(b)}`;
}

export function isValidHex(hex: string): boolean {
  return HEX.test(hex.trim());
}

/** Squared RGB distance (monotonic; avoids a sqrt per comparison). */
export function colorDistanceSq(a: number[], b: number[]): number {
  const dr = a[0] - b[0];
  const dg = a[1] - b[1];
  const db = a[2] - b[2];
  return dr * dr + dg * dg + db * db;
}

/** Index of the palette entry nearest to `color` (a [r,g,b] triple). */
export function nearestPaletteIndex(palette: string[], color: number[]): number {
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < palette.length; i++) {
    const d = colorDistanceSq(hexToRgb(palette[i]), color);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

// The Document is the mutable model the UI drives. It owns the DocState plus
// unlimited snapshot-based undo/redo, and exposes named operations for every
// editing action. Pure state (DocState) lives in types.ts; everything here is
// framework-agnostic and unit-tested.

import {
  type DocState,
  type LayerState,
  createInitialState,
  createLayer,
  emptyCel,
  MAX_DURATION,
  MAX_FPS,
  MAX_FRAMES,
  MAX_LAYERS,
} from './types';
import { compositeFrame, compositeOnChecker } from './composite';
import { type RGBA } from './composite';

export class History {
  private undo: DocState[] = [];
  private redo: DocState[] = [];

  constructor(private get: () => DocState, private set: (s: DocState) => void) {}

  push(): void {
    this.undo.push(structuredClone(this.get()));
    this.redo.length = 0;
  }

  undoStep(): boolean {
    if (!this.undo.length) return false;
    this.redo.push(structuredClone(this.get()));
    this.set(this.undo.pop() as DocState);
    return true;
  }

  redoStep(): boolean {
    if (!this.redo.length) return false;
    this.undo.push(structuredClone(this.get()));
    this.set(this.redo.pop() as DocState);
    return true;
  }

  get canUndo(): boolean {
    return this.undo.length > 0;
  }

  get canRedo(): boolean {
    return this.redo.length > 0;
  }

  /** Drop all history (used after loading a project or clearing). */
  clear(): void {
    this.undo.length = 0;
    this.redo.length = 0;
  }

  get depth(): number {
    return this.undo.length;
  }
}

type Listener = () => void;

export class Document {
  private state: DocState;
  private history: History;
  private listeners = new Set<Listener>();

  constructor(state?: DocState) {
    this.state = state ? structuredClone(state) : createInitialState();
    this.history = new History(
      () => this.state,
      (s) => {
        this.state = s;
      }
    );
  }

  subscribe(fn: Listener): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  private emit(): void {
    for (const fn of this.listeners) fn();
  }

  getState(): DocState {
    return this.state;
  }

  /** Replace the whole document (used for load/new). Resets history. */
  loadState(state: DocState): void {
    this.state = structuredClone(state);
    this.history.clear();
    this.emit();
  }

  // ---- history controls -------------------------------------------------

  /** Snapshot the current state as the undo point. Call before a mutation. */
  pushHistory(): void {
    this.history.push();
    this.emit();
  }

  undo(): void {
    if (this.history.undoStep()) this.emit();
  }

  redo(): void {
    if (this.history.redoStep()) this.emit();
  }

  get canUndo(): boolean {
    return this.history.canUndo;
  }

  get canRedo(): boolean {
    return this.history.canRedo;
  }

  // ---- active cel helpers ----------------------------------------------

  getActiveCel(): number[] {
    const s = this.state;
    const frame = s.frames[s.activeFrame];
    return frame.cels[s.activeLayer];
  }

  /** Write paletteIndex (-1 to erase) at each point. Does NOT push history. */
  applyPoints(points: ReadonlyArray<readonly [number, number]>, paletteIndex: number): void {
    const s = this.state;
    const cel = this.getActiveCel();
    for (const [x, y] of points) {
      if (x < 0 || y < 0 || x >= s.width || y >= s.height) continue;
      cel[y * s.width + x] = paletteIndex;
    }
    this.emit();
  }

  /** Read the composited color index at a pixel (topmost visible layer). */
  pickIndexAt(x: number, y: number): number {
    const s = this.state;
    if (x < 0 || y < 0 || x >= s.width || y >= s.height) return -1;
    const frame = s.frames[s.activeFrame];
    const p = y * s.width + x;
    // Top-most wins, so iterate from the last layer downward.
    for (let li = s.layers.length - 1; li >= 0; li--) {
      if (!s.layers[li].visible) continue;
      const idx = frame.cels[li][p];
      if (idx >= 0) return idx;
    }
    return -1;
  }

  /**
   * Write RGBA pixels (from an imported image) into the active cel, quantizing
   * to the current palette. Fully transparent source pixels stay transparent.
   */
  importRgbaIntoActiveCel(rgba: Uint8ClampedArray, quantize: (r: number, g: number, b: number, a: number) => number): void {
    const s = this.state;
    const cel = this.getActiveCel();
    for (let p = 0; p < s.width * s.height; p++) {
      const a = rgba[p * 4 + 3];
      if (a < 8) {
        cel[p] = -1;
        continue;
      }
      cel[p] = quantize(rgba[p * 4], rgba[p * 4 + 1], rgba[p * 4 + 2], a);
    }
    this.emit();
  }

  // ---- settings ---------------------------------------------------------

  setTool(tool: DocState['tool']): void {
    this.state.tool = tool;
    this.emit();
  }

  setBrushSize(size: number): void {
    this.state.brushSize = size === 2 ? 2 : 1;
    this.emit();
  }

  cycleBrush(dir: 1 | -1): void {
    const next = this.state.brushSize === 1 ? 2 : 1;
    this.state.brushSize = next;
    void dir;
    this.emit();
  }

  setActiveColor(index: number): void {
    if (index >= 0 && index < this.state.palette.length) {
      this.state.activeColor = index;
      this.emit();
    }
  }

  setFps(fps: number): void {
    this.state.fps = clamp(fps, 1, MAX_FPS);
    this.emit();
  }

  setLoop(loop: boolean): void {
    this.state.loop = loop;
    this.emit();
  }

  setOnionSkin(on: boolean): void {
    this.state.onionSkin = on;
    this.emit();
  }

  setOnionOpacity(v: number): void {
    this.state.onionOpacity = clamp(v, 0, 100);
    this.emit();
  }

  // ---- palette ----------------------------------------------------------

  addColor(hex: string): number {
    this.history.push();
    this.state.palette.push(hex);
    this.state.activeColor = this.state.palette.length - 1;
    this.emit();
    return this.state.palette.length - 1;
  }

  setPaletteColor(index: number, hex: string): void {
    if (index < 0 || index >= this.state.palette.length) return;
    this.history.push();
    this.state.palette[index] = hex;
    this.emit();
  }

  removeColor(index: number): void {
    if (index < 0 || index >= this.state.palette.length) return;
    if (this.state.palette.length <= 1) return;
    this.history.push();
    // Remap cels: removed index -> -1, higher indices shift down by one.
    for (const frame of this.state.frames) {
      for (const cel of frame.cels) {
        for (let p = 0; p < cel.length; p++) {
          const v = cel[p];
          if (v === index) cel[p] = -1;
          else if (v > index) cel[p] = v - 1;
        }
      }
    }
    this.state.palette.splice(index, 1);
    if (this.state.activeColor >= this.state.palette.length) {
      this.state.activeColor = this.state.palette.length - 1;
    } else if (this.state.activeColor > index) {
      this.state.activeColor -= 1;
    } else if (this.state.activeColor === index) {
      this.state.activeColor = 0;
    }
    this.emit();
  }

  moveColor(from: number, to: number): void {
    const pal = this.state.palette;
    if (from < 0 || from >= pal.length || to < 0 || to >= pal.length || from === to) return;
    this.history.push();
    const activeColorIndex = pal[this.state.activeColor];
    const [moved] = pal.splice(from, 1);
    pal.splice(to, 0, moved);
    // Keep the active color pointing at the same swatch value.
    const newActive = pal.indexOf(activeColorIndex);
    this.state.activeColor = newActive >= 0 ? newActive : 0;
    this.emit();
  }

  loadPalette(colors: string[]): void {
    if (!colors.length) return;
    this.history.push();
    // Remap any out-of-range active color.
    this.state.palette = colors.slice();
    if (this.state.activeColor >= colors.length) this.state.activeColor = 0;
    this.emit();
  }

  // ---- layers -----------------------------------------------------------

  /** Insert a new empty layer above the active layer. */
  addLayer(): number {
    if (this.state.layers.length >= MAX_LAYERS) return this.state.activeLayer;
    this.history.push();
    const layer = createLayer(`Layer ${this.state.layers.length + 1}`);
    const insertAt = this.state.activeLayer + 1;
    this.state.layers.splice(insertAt, 0, layer);
    for (const frame of this.state.frames) {
      frame.cels.splice(insertAt, 0, emptyCel(this.state.width, this.state.height));
    }
    this.state.activeLayer = insertAt;
    this.emit();
    return insertAt;
  }

  deleteLayer(index: number): void {
    if (this.state.layers.length <= 1) return; // keep at least one layer
    this.history.push();
    this.state.layers.splice(index, 1);
    for (const frame of this.state.frames) frame.cels.splice(index, 1);
    if (this.state.activeLayer >= this.state.layers.length) {
      this.state.activeLayer = this.state.layers.length - 1;
    }
    this.emit();
  }

  renameLayer(index: number, name: string): void {
    if (index < 0 || index >= this.state.layers.length) return;
    this.history.push();
    this.state.layers[index].name = name;
    this.emit();
  }

  setLayerVisible(index: number, visible: boolean): void {
    if (index < 0 || index >= this.state.layers.length) return;
    this.history.push();
    this.state.layers[index].visible = visible;
    this.emit();
  }

  setLayerOpacity(index: number, opacity: number): void {
    if (index < 0 || index >= this.state.layers.length) return;
    this.history.push();
    this.state.layers[index].opacity = clamp(opacity, 0, 100);
    this.emit();
  }

  setActiveLayer(index: number): void {
    if (index < 0 || index >= this.state.layers.length) return;
    this.state.activeLayer = index;
    this.emit();
  }

  /** Move a layer up (toward top) or down by one. Returns new index. */
  moveLayer(index: number, dir: 1 | -1): number {
    const n = this.state.layers.length;
    const target = dir === 1 ? index + 1 : index - 1;
    if (target < 0 || target >= n) return index;
    this.history.push();
    swap(this.state.layers, index, target);
    for (const frame of this.state.frames) swap(frame.cels, index, target);
    if (this.state.activeLayer === index) this.state.activeLayer = target;
    else if (this.state.activeLayer === target) this.state.activeLayer = index;
    this.emit();
    return target;
  }

  /** Move a layer to an explicit index (drag reorder). */
  reorderLayer(from: number, to: number): void {
    const n = this.state.layers.length;
    if (from < 0 || from >= n || to < 0 || to >= n || from === to) return;
    this.history.push();
    const activeWas = this.state.activeLayer;
    const [layer] = this.state.layers.splice(from, 1);
    this.state.layers.splice(to, 0, layer);
    for (const frame of this.state.frames) {
      const [cel] = frame.cels.splice(from, 1);
      frame.cels.splice(to, 0, cel);
    }
    this.state.activeLayer = reindex(activeWas, from, to);
    this.emit();
  }

  // ---- frames -----------------------------------------------------------

  addFrame(): number {
    if (this.state.frames.length >= MAX_FRAMES) return this.state.activeFrame;
    this.history.push();
    const cels = this.state.layers.map(() => emptyCel(this.state.width, this.state.height));
    const prev = this.state.frames[this.state.activeFrame];
    const idx = this.state.activeFrame + 1;
    this.state.frames.splice(idx, 0, { duration: prev ? prev.duration : 4, cels });
    this.state.activeFrame = idx;
    this.emit();
    return idx;
  }

  duplicateFrame(index: number): number {
    if (this.state.frames.length >= MAX_FRAMES) return this.state.activeFrame;
    this.history.push();
    const src = this.state.frames[index];
    const cels = src.cels.map((c) => c.slice());
    const idx = index + 1;
    this.state.frames.splice(idx, 0, { duration: src.duration, cels });
    this.state.activeFrame = idx;
    this.emit();
    return idx;
  }

  deleteFrame(index: number): void {
    if (this.state.frames.length <= 1) return; // keep at least one frame
    this.history.push();
    this.state.frames.splice(index, 1);
    if (this.state.activeFrame >= this.state.frames.length) {
      this.state.activeFrame = this.state.frames.length - 1;
    }
    this.emit();
  }

  reorderFrame(from: number, to: number): void {
    const n = this.state.frames.length;
    if (from < 0 || from >= n || to < 0 || to >= n || from === to) return;
    this.history.push();
    const activeWas = this.state.activeFrame;
    const [frame] = this.state.frames.splice(from, 1);
    this.state.frames.splice(to, 0, frame);
    this.state.activeFrame = reindex(activeWas, from, to);
    this.emit();
  }

  setActiveFrame(index: number): void {
    if (index < 0 || index >= this.state.frames.length) return;
    this.state.activeFrame = index;
    this.emit();
  }

  setFrameDuration(index: number, duration: number): void {
    if (index < 0 || index >= this.state.frames.length) return;
    this.history.push();
    this.state.frames[index].duration = clamp(Math.round(duration), 1, MAX_DURATION);
    this.emit();
  }

  // ---- rendering helpers ------------------------------------------------

  composite(frameIndex = this.state.activeFrame): RGBA {
    return compositeFrame(this.state, frameIndex);
  }

  compositeChecker(frameIndex = this.state.activeFrame): RGBA {
    return compositeOnChecker(this.state, frameIndex);
  }

  get width(): number {
    return this.state.width;
  }

  get height(): number {
    return this.state.height;
  }
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}

function swap<T>(arr: T[], a: number, b: number): void {
  const t = arr[a];
  arr[a] = arr[b];
  arr[b] = t;
}

/** Where an index lands after moving `from` to position `to` (array splice semantics). */
function reindex(old: number, from: number, to: number): number {
  let result = old;
  if (old === from) result = to;
  else if (from < to && old > from && old <= to) result = old - 1;
  else if (from > to && old >= to && old < from) result = old + 1;
  return result;
}

export type { LayerState };

// Run-length encoding for cel arrays. Cels are number[] of small integers
// (-1 and palette indices); RLE keeps project files compact while remaining
// perfectly lossless on round-trip.

export function rleEncode(values: number[]): string {
  const parts: string[] = [];
  let i = 0;
  const n = values.length;
  while (i < n) {
    const v = values[i];
    let run = 1;
    while (i + run < n && values[i + run] === v) run++;
    parts.push(`${v}:${run}`);
    i += run;
  }
  return parts.join(',');
}

export function rleDecode(text: string, length: number): number[] {
  const out = new Array<number>(length);
  let pos = 0;
  if (text === '') {
    if (length !== 0) throw new Error('Empty RLE but length > 0');
    return out;
  }
  for (const part of text.split(',')) {
    const [vStr, cStr] = part.split(':');
    const v = Number(vStr);
    const c = Number(cStr);
    if (!Number.isInteger(v) || !Number.isInteger(c) || c <= 0) {
      throw new Error(`Bad RLE segment: ${part}`);
    }
    for (let k = 0; k < c; k++) out[pos++] = v;
  }
  if (pos !== length) throw new Error(`RLE length mismatch: got ${pos}, expected ${length}`);
  return out;
}

// `.spriteforge` project file format: a JSON document (see README for the
// documented schema). Cels are RLE-encoded for compactness but the round-trip
// is lossless for pixels, palette, layers, frame order, durations, fps,
// onion/loop state and tool settings.

import type { DocState, FrameState, LayerState, ToolId } from '../model/types';
import { isValidHex } from '../model/color';
import { rleDecode, rleEncode } from './rle';

export const PROJECT_FORMAT = 'spriteforge';
export const PROJECT_VERSION = 1;

interface CelDTO {
  rle: string;
}
interface FrameDTO {
  duration: number;
  cels: CelDTO[];
}
interface LayerDTO {
  id: string;
  name: string;
  visible: boolean;
  opacity: number;
}
export interface ProjectDTO {
  format: typeof PROJECT_FORMAT;
  version: number;
  doc: {
    width: number;
    height: number;
    palette: string[];
    activeColor: number;
    layers: LayerDTO[];
    frames: FrameDTO[];
    activeFrame: number;
    activeLayer: number;
    fps: number;
    loop: boolean;
    onionSkin: boolean;
    onionOpacity: number;
    tool: ToolId;
    brushSize: number;
  };
}

const TOOLS: ToolId[] = ['pencil', 'eraser', 'line', 'rect', 'ellipse', 'fill', 'picker'];

export function serializeProject(state: DocState): string {
  const dto: ProjectDTO = {
    format: PROJECT_FORMAT,
    version: PROJECT_VERSION,
    doc: {
      width: state.width,
      height: state.height,
      palette: state.palette.slice(),
      activeColor: state.activeColor,
      layers: state.layers.map((l) => ({ id: l.id, name: l.name, visible: l.visible, opacity: l.opacity })),
      frames: state.frames.map((f) => ({
        duration: f.duration,
        cels: f.cels.map((cel) => ({ rle: rleEncode(cel) })),
      })),
      activeFrame: state.activeFrame,
      activeLayer: state.activeLayer,
      fps: state.fps,
      loop: state.loop,
      onionSkin: state.onionSkin,
      onionOpacity: state.onionOpacity,
      tool: state.tool,
      brushSize: state.brushSize,
    },
  };
  return JSON.stringify(dto, null, 0);
}

function isTool(v: unknown): v is ToolId {
  return typeof v === 'string' && (TOOLS as string[]).includes(v);
}

export function deserializeProject(text: string): DocState {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    throw new Error(`Not a valid .spriteforge file: ${(e as Error).message}`);
  }
  if (!parsed || typeof parsed !== 'object') throw new Error('Project is not an object');
  const dto = parsed as Partial<ProjectDTO>;
  if (dto.format !== PROJECT_FORMAT) throw new Error('Not a spriteforge project (missing format tag)');
  if (dto.version !== PROJECT_VERSION) throw new Error(`Unsupported project version: ${dto.version}`);
  const d = dto.doc;
  if (!d) throw new Error('Project missing doc');
  if (
    typeof d.width !== 'number' ||
    typeof d.height !== 'number' ||
    d.width <= 0 ||
    d.height <= 0
  ) {
    throw new Error('Project has invalid dimensions');
  }
  if (!Array.isArray(d.palette) || d.palette.length === 0 || !d.palette.every(isValidHex)) {
    throw new Error('Project has an invalid palette');
  }
  if (!Array.isArray(d.layers) || d.layers.length === 0) throw new Error('Project has no layers');
  if (!Array.isArray(d.frames) || d.frames.length === 0) throw new Error('Project has no frames');
  const pixelCount = d.width * d.height;

  const layers: LayerState[] = d.layers.map((l, i) => ({
    id: typeof l.id === 'string' ? l.id : `layer-${i}`,
    name: typeof l.name === 'string' ? l.name : `Layer ${i + 1}`,
    visible: l.visible !== false,
    opacity: clampInt(l.opacity, 0, 100, 100),
  }));

  const frames: FrameState[] = d.frames.map((f) => {
    if (!Array.isArray(f.cels) || f.cels.length !== layers.length) {
      throw new Error('A frame has the wrong number of layers');
    }
    const cels = f.cels.map((cel) => {
      const decoded = rleDecode(cel.rle, pixelCount);
      for (const v of decoded) {
        if (v < -1 || v >= d.palette.length) throw new Error('Cel references a color outside the palette');
      }
      return decoded;
    });
    return { duration: clampInt(f.duration, 1, 24, 4), cels };
  });

  const state: DocState = {
    width: d.width,
    height: d.height,
    palette: d.palette.slice(),
    activeColor: clampInt(d.activeColor, 0, d.palette.length - 1, 0),
    layers,
    frames,
    activeFrame: clampInt(d.activeFrame, 0, frames.length - 1, 0),
    activeLayer: clampInt(d.activeLayer, 0, layers.length - 1, 0),
    fps: clampInt(d.fps, 1, 24, 8),
    loop: d.loop !== false,
    onionSkin: d.onionSkin === true,
    onionOpacity: clampInt(d.onionOpacity, 0, 100, 30),
    tool: isTool(d.tool) ? d.tool : 'pencil',
    brushSize: d.brushSize === 2 ? 2 : 1,
  };
  return state;
}

function clampInt(v: unknown, lo: number, hi: number, fallback: number): number {
  if (typeof v !== 'number' || !Number.isFinite(v)) return fallback;
  return Math.max(lo, Math.min(hi, Math.round(v)));
}

// Pure sprite-sheet assembly. Given composited frame buffers (RGBA8, all the
// same size), lay them out in a row-major grid with a uniform gutter and return
// a single RGBA8 sheet. The UI just blits the result to a canvas for download.

import type { RGBA } from '../model/composite';
import { blankRGBA } from '../model/composite';

export interface SpritesheetLayout {
  cols: number;
  rows: number;
  cellWidth: number;
  cellHeight: number;
  padding: number;
  width: number;
  height: number;
  /** Top-left pixel of each frame cell, in row-major order. */
  positions: { x: number; y: number }[];
}

/** Uniform gutter: padding is applied around the sheet and between every cell. */
export function computeSpritesheetLayout(
  frameCount: number,
  cellWidth: number,
  cellHeight: number,
  cols: number,
  padding: number
): SpritesheetLayout {
  const n = Math.max(1, frameCount);
  const c = Math.max(1, Math.min(cols, n));
  const rows = Math.ceil(n / c);
  const width = c * cellWidth + (c + 1) * padding;
  const height = rows * cellHeight + (rows + 1) * padding;
  const positions: { x: number; y: number }[] = [];
  for (let i = 0; i < n; i++) {
    const col = i % c;
    const row = Math.floor(i / c);
    positions.push({
      x: padding + col * (cellWidth + padding),
      y: padding + row * (cellHeight + padding),
    });
  }
  return { cols: c, rows, cellWidth, cellHeight, padding, width, height, positions };
}

export function buildSpritesheet(frames: RGBA[], cols: number, padding: number): SpritesheetLayout & { data: Uint8ClampedArray } {
  if (!frames.length) throw new Error('No frames to lay out');
  const cellWidth = frames[0].width;
  const cellHeight = frames[0].height;
  const layout = computeSpritesheetLayout(frames.length, cellWidth, cellHeight, cols, padding);
  const out = blankRGBA(layout.width, layout.height);
  frames.forEach((frame, i) => {
    const { x, y } = layout.positions[i];
    for (let fy = 0; fy < cellHeight; fy++) {
      for (let fx = 0; fx < cellWidth; fx++) {
        const src = (fy * cellWidth + fx) * 4;
        const dst = ((y + fy) * layout.width + (x + fx)) * 4;
        out.data[dst] = frame.data[src];
        out.data[dst + 1] = frame.data[src + 1];
        out.data[dst + 2] = frame.data[src + 2];
        out.data[dst + 3] = frame.data[src + 3];
      }
    }
  });
  return { ...layout, data: out.data };
}

// Animated GIF encoding. Because SpriteForge's model is already palette-based,
// we build the GIF palette straight from the document palette (opaque colors)
// plus one reserved transparent index, and map pixels with our own nearest-
// color lookup. This is faster and more faithful for flat pixel art than
// re-quantizing every frame, and gives clean 1-bit transparency.

import { GIFEncoder, type Palette } from 'gifenc';
import type { RGBA } from '../model/composite';
import { hexToRgb, nearestPaletteIndex } from '../model/color';

export interface GifFrameInput {
  rgba: RGBA;
  /** Hold duration in units of the playback rate. */
  duration: number;
}

export interface EncodeGifOptions {
  palette: string[]; // "#rrggbb" document palette
  fps: number;
  loop: boolean;
}

export function encodeGif(frames: GifFrameInput[], opts: EncodeGifOptions): Uint8Array {
  if (!frames.length) throw new Error('No frames to encode');
  if (!opts.palette.length) throw new Error('Empty palette');

  const { width, height } = frames[0].rgba;
  const palette: Palette = opts.palette.map(hexToRgb);
  const transparentIndex = palette.length;
  palette.push([0, 0, 0]); // reserved transparent entry

  const encoder = GIFEncoder();
  frames.forEach((frame, i) => {
    if (frame.rgba.width !== width || frame.rgba.height !== height) {
      throw new Error('All frames must share a size');
    }
    const index = new Uint8Array(width * height);
    const src = frame.rgba.data;
    for (let p = 0; p < width * height; p++) {
      const a = src[p * 4 + 3];
      if (a < 128) {
        index[p] = transparentIndex;
      } else {
        index[p] = nearestPaletteIndex(opts.palette, [src[p * 4], src[p * 4 + 1], src[p * 4 + 2]]);
      }
    }
    const delay = Math.max(2, Math.round((frame.duration / opts.fps) * 100));
    encoder.writeFrame(index, width, height, {
      palette,
      delay,
      transparent: true,
      transparentIndex,
      repeat: i === 0 ? (opts.loop ? 0 : 1) : undefined,
    });
  });
  encoder.finish();
  return encoder.bytes();
}

// Import pipeline helpers: nearest-neighbor downscale of an oversized RGBA
// buffer to the canvas size, and quantization of an RGBA buffer to palette
// indices. Both are pure so the lossy parts of import are unit-tested; the UI
// only decodes the PNG (canvas) and hands us pixels.

import type { RGBA } from '../model/composite';
import { blankRGBA } from '../model/composite';
import { nearestPaletteIndex } from '../model/color';

/**
 * Nearest-neighbor resample to dstW×dstH. If the source is already exactly the
 * destination size it is returned unchanged (a copy). Larger sources are
 * downscaled; this is a pure pixel resample, alpha is preserved.
 */
export function resampleNearest(src: RGBA, dstW: number, dstH: number): RGBA {
  if (src.width === dstW && src.height === dstH) {
    return { width: dstW, height: dstH, data: src.data.slice() };
  }
  const out = blankRGBA(dstW, dstH);
  for (let y = 0; y < dstH; y++) {
    const sy = Math.min(src.height - 1, Math.floor((y * src.height) / dstH));
    for (let x = 0; x < dstW; x++) {
      const sx = Math.min(src.width - 1, Math.floor((x * src.width) / dstW));
      const s = (sy * src.width + sx) * 4;
      const d = (y * dstW + x) * 4;
      out.data[d] = src.data[s];
      out.data[d + 1] = src.data[s + 1];
      out.data[d + 2] = src.data[s + 2];
      out.data[d + 3] = src.data[s + 3];
    }
  }
  return out;
}

/** Convert an RGBA buffer (already canvas-sized) into a palette-indexed cel. */
export function quantizeRgbaToCel(rgba: RGBA, palette: string[]): number[] {
  const n = rgba.width * rgba.height;
  const cel = new Array<number>(n);
  for (let p = 0; p < n; p++) {
    const a = rgba.data[p * 4 + 3];
    if (a < 8) {
      cel[p] = -1;
      continue;
    }
    cel[p] = nearestPaletteIndex(palette, [rgba.data[p * 4], rgba.data[p * 4 + 1], rgba.data[p * 4 + 2]]);
  }
  return cel;
}

import { describe, it, expect } from 'vitest';
import { linePoints, rectPoints, ellipsePoints, floodFill, brushPoints, brushStroke } from './geometry';

describe('linePoints (Bresenham)', () => {
  it('connects endpoints inclusive on a diagonal', () => {
    const pts = linePoints(0, 0, 3, 3);
    expect(pts[0]).toEqual([0, 0]);
    expect(pts[pts.length - 1]).toEqual([3, 3]);
    expect(pts).toHaveLength(4);
  });

  it('draws a horizontal run', () => {
    const pts = linePoints(1, 2, 5, 2);
    expect(pts).toEqual([
      [1, 2],
      [2, 2],
      [3, 2],
      [4, 2],
      [5, 2],
    ]);
  });

  it('handles reversed direction', () => {
    const pts = linePoints(5, 0, 2, 0);
    expect(pts.map((p) => p[0])).toEqual([5, 4, 3, 2]);
  });

  it('is a single point when start==end', () => {
    expect(linePoints(4, 4, 4, 4)).toEqual([[4, 4]]);
  });
});

describe('rectPoints', () => {
  it('traces the outline of a 3x3 box', () => {
    const pts = rectPoints(0, 0, 2, 2);
    // corners present
    expect(pts).toEqual(expect.arrayContaining([[0, 0], [2, 0], [0, 2], [2, 2]]));
    // interior not present
    expect(pts).not.toEqual(expect.arrayContaining([[1, 1]]));
  });

  it('fills when fill=true', () => {
    const pts = rectPoints(0, 0, 1, 1, true);
    expect(pts).toHaveLength(4);
  });

  it('normalizes reversed corners', () => {
    const a = rectPoints(3, 3, 0, 0).sort();
    const b = rectPoints(0, 0, 3, 3).sort();
    expect(a).toEqual(b);
  });
});

describe('ellipsePoints', () => {
  it('stays within the bounding box', () => {
    const pts = ellipsePoints(2, 2, 9, 5);
    for (const [x, y] of pts) {
      expect(x).toBeGreaterThanOrEqual(2);
      expect(x).toBeLessThanOrEqual(9);
      expect(y).toBeGreaterThanOrEqual(2);
      expect(y).toBeLessThanOrEqual(5);
    }
  });

  it('hits the four extreme edge midpoints', () => {
    const pts = new Set(ellipsePoints(0, 0, 8, 4).map((p) => `${p[0]},${p[1]}`));
    // left/right mid, top/bottom mid
    expect(pts.has('0,2')).toBe(true);
    expect(pts.has('8,2')).toBe(true);
    expect(pts.has('4,0')).toBe(true);
    expect(pts.has('4,4')).toBe(true);
  });

  it('degenerates to one point', () => {
    expect(ellipsePoints(3, 3, 3, 3)).toEqual([[3, 3]]);
  });

  it('fill covers the center', () => {
    const pts = new Set(ellipsePoints(0, 0, 6, 6, true).map((p) => `${p[0]},${p[1]}`));
    expect(pts.has('3,3')).toBe(true);
    expect(pts.has('0,0')).toBe(false);
  });
});

describe('floodFill', () => {
  const w = 5;
  const h = 5;
  const cel = new Array(w * h).fill(-1);

  it('fills a connected transparent region', () => {
    const pts = floodFill(cel, w, h, 0, 0, -1, 3);
    expect(pts).toHaveLength(w * h);
    expect(pts).toEqual(expect.arrayContaining([[0, 0], [4, 4], [2, 2]]));
  });

  it('stops at pixels with a different value', () => {
    const wall = cel.slice();
    for (let y = 0; y < h; y++) wall[y * w + 2] = 5; // vertical wall at x=2
    const pts = floodFill(wall, w, h, 0, 0, -1, 1);
    expect(pts.every(([, y]) => y >= 0 && y < h)).toBe(true);
    // Nothing to the right of the wall should be included
    expect(pts.some((x) => x[0] === 3)).toBe(false);
  });

  it('is a no-op when the target equals the replacement', () => {
    const already = new Array(w * h).fill(2);
    expect(floodFill(already, w, h, 0, 0, 2, 2)).toEqual([]);
  });

  it('returns empty for an out-of-bounds seed', () => {
    expect(floodFill(cel, w, h, -1, 0, -1, 1)).toEqual([]);
  });
});

describe('brush', () => {
  it('1px brush is a single point', () => {
    expect(brushPoints(2, 2, 1, 10, 10)).toEqual([[2, 2]]);
  });

  it('2px brush is a 2x2 block', () => {
    expect(brushPoints(2, 2, 2, 10, 10)).toHaveLength(4);
  });

  it('clips to the canvas bounds', () => {
    expect(brushPoints(9, 9, 2, 10, 10)).toEqual([[9, 9]]);
  });

  it('stroke covers every pixel along the segment', () => {
    const pts = brushStroke(0, 0, 3, 0, 1, 10, 10);
    expect(pts).toEqual(expect.arrayContaining([[0, 0], [1, 0], [2, 0], [3, 0]]));
  });
});

