import { describe, it, expect, beforeEach } from 'vitest';
import { Document } from './document';

describe('Document', () => {
  let doc: Document;
  beforeEach(() => {
    doc = new Document();
  });

  it('starts with 4 layers and 1 frame', () => {
    const s = doc.getState();
    expect(s.layers).toHaveLength(4);
    expect(s.frames).toHaveLength(1);
    expect(s.palette.length).toBeGreaterThanOrEqual(16);
  });

  it('applyPoints writes palette index and -1 erases', () => {
    doc.pushHistory();
    doc.applyPoints([[0, 0], [1, 1]], 3);
    expect(doc.getActiveCel()[0]).toBe(3);
    expect(doc.getActiveCel()[1 * doc.width + 1]).toBe(3);
    doc.applyPoints([[0, 0]], -1);
    expect(doc.getActiveCel()[0]).toBe(-1);
  });

  it('undo reverts the last pushed mutation', () => {
    doc.pushHistory();
    doc.applyPoints([[0, 0]], 5);
    expect(doc.getActiveCel()[0]).toBe(5);
    doc.undo();
    expect(doc.getActiveCel()[0]).toBe(-1);
  });

  it('redo re-applies after undo', () => {
    doc.pushHistory();
    doc.applyPoints([[0, 0]], 5);
    doc.undo();
    doc.redo();
    expect(doc.getActiveCel()[0]).toBe(5);
  });

  it('reports undo/redo availability', () => {
    expect(doc.canUndo).toBe(false);
    doc.pushHistory();
    doc.applyPoints([[0, 0]], 1);
    expect(doc.canUndo).toBe(true);
    expect(doc.canRedo).toBe(false);
    doc.undo();
    expect(doc.canRedo).toBe(true);
  });

  it('addLayer inserts above the active layer with a cel on every frame', () => {
    doc.addFrame(); // now 2 frames
    doc.setActiveLayer(0);
    const before = doc.getState().layers.length;
    doc.addLayer();
    const s = doc.getState();
    expect(s.layers.length).toBe(before + 1);
    expect(s.activeLayer).toBe(1);
    for (const f of s.frames) {
      expect(f.cels.length).toBe(s.layers.length);
      expect(f.cels[1]).toHaveLength(doc.width * doc.height);
    }
  });

  it('deleteLayer keeps at least one layer and removes cels', () => {
    doc.setActiveLayer(1);
    doc.deleteLayer(1);
    expect(doc.getState().layers.length).toBe(3);
    expect(doc.getState().frames[0].cels.length).toBe(3);
  });

  it('moveLayer swaps both metadata and cels', () => {
    doc.getState().frames[0].cels[0][0] = 7;
    doc.pushHistory();
    doc.moveLayer(0, 1); // move bottom up
    expect(doc.getState().frames[0].cels[1][0]).toBe(7);
    expect(doc.getState().frames[0].cels[0][0]).toBe(-1);
  });

  it('reorderLayer reindexes the active layer', () => {
    doc.setActiveLayer(0);
    doc.reorderLayer(0, 3); // bottom -> top
    expect(doc.getState().activeLayer).toBe(3);
    doc.reorderLayer(3, 0);
    expect(doc.getState().activeLayer).toBe(0);
  });

  it('frame operations: add, duplicate, delete, reorder', () => {
    doc.getState().frames[0].cels[0][0] = 4;
    doc.duplicateFrame(0);
    expect(doc.getState().frames).toHaveLength(2);
    expect(doc.getState().activeFrame).toBe(1);
    expect(doc.getState().frames[1].cels[0][0]).toBe(4); // copied
    doc.getState().frames[1].cels[0][0] = 9;
    doc.reorderFrame(1, 0);
    expect(doc.getState().activeFrame).toBe(0); // active followed the frame
    expect(doc.getState().frames[0].cels[0][0]).toBe(9);
    doc.deleteFrame(1);
    expect(doc.getState().frames).toHaveLength(1);
  });

  it('clamps durations and refuses to delete the last frame', () => {
    doc.setFrameDuration(0, 999);
    expect(doc.getState().frames[0].duration).toBe(24);
    doc.setFrameDuration(0, 0);
    expect(doc.getState().frames[0].duration).toBe(1);
    doc.deleteFrame(0);
    expect(doc.getState().frames).toHaveLength(1);
  });

  it('addColor appends and selects; setPaletteColor edits in place', () => {
    const n = doc.getState().palette.length;
    const idx = doc.addColor('#123456');
    expect(idx).toBe(n);
    expect(doc.getState().activeColor).toBe(n);
    doc.setPaletteColor(idx, '#654321');
    expect(doc.getState().palette[idx]).toBe('#654321');
  });

  it('removeColor remaps cels: removed -> transparent, higher shift down', () => {
    const s = doc.getState();
    // palette[2] referenced by a cel pixel; palette[3] should shift to 2.
    s.frames[0].cels[0][0] = 3;
    doc.pushHistory();
    doc.removeColor(2);
    expect(doc.getActiveCel()[0]).toBe(2); // was 3, shifted down
    s.frames[0].cels[0][1] = 2;
    doc.pushHistory();
    doc.removeColor(2);
    expect(doc.getActiveCel()[1]).toBe(-1);
  });

  it('moveColor keeps activeColor pointing at the same swatch value', () => {
    doc.setActiveColor(1);
    const value = doc.getState().palette[1];
    doc.moveColor(1, 5);
    expect(doc.getState().palette[doc.getState().activeColor]).toBe(value);
  });

  it('fps clamps to the 1..24 range', () => {
    doc.setFps(100);
    expect(doc.getState().fps).toBe(24);
    doc.setFps(-5);
    expect(doc.getState().fps).toBe(1);
  });

  it('emits to subscribers on change', () => {
    let count = 0;
    const off = doc.subscribe(() => count++);
    doc.pushHistory();
    doc.applyPoints([[0, 0]], 1);
    expect(count).toBeGreaterThan(0);
    off();
    const before = count;
    doc.applyPoints([[1, 1]], 1);
    expect(count).toBe(before);
  });
});

import { describe, it, expect } from 'vitest';
import { rleEncode, rleDecode } from './rle';

describe('rle', () => {
  it('round-trips arbitrary arrays', () => {
    const samples: number[][] = [
      [],
      [-1],
      [-1, -1, -1, 0, 1, 1, 2, 2, 2, 2, -1],
      new Array(1024).fill(-1),
      Array.from({ length: 100 }, (_, i) => i % 7),
    ];
    for (const s of samples) {
      expect(rleDecode(rleEncode(s), s.length)).toEqual(s);
    }
  });

  it('compresses long runs', () => {
    const s = new Array(1000).fill(5);
    const enc = rleEncode(s);
    expect(enc).toBe('5:1000');
    expect(enc.length).toBeLessThan(s.length);
  });

  it('throws on a length mismatch', () => {
    expect(() => rleDecode('1:3', 5)).toThrow(/mismatch/);
  });

  it('throws on malformed segments', () => {
    expect(() => rleDecode('a:b', 2)).toThrow();
    expect(() => rleDecode('1:0', 1)).toThrow();
  });
});

import { describe, it, expect } from 'vitest';
import { createInitialState } from '../model/types';
import { serializeProject, deserializeProject, PROJECT_FORMAT } from './project';

function richState() {
  const s = createInitialState();
  s.tool = 'rect';
  s.brushSize = 2;
  s.activeColor = 6;
  s.fps = 12;
  s.loop = false;
  s.onionSkin = true;
  s.onionOpacity = 55;
  s.layers[0].name = 'BG';
  s.layers[1].opacity = 42;
  s.layers[2].visible = false;
  s.frames[0].duration = 7;
  s.frames[0].cels[0][0] = 4;
  s.frames[0].cels[0][10] = 15;
  s.frames[0].cels[1][100] = 2;
  // second frame with distinct pixels + duration
  s.frames.push({
    duration: 3,
    cels: s.layers.map(() => new Array(s.width * s.height).fill(-1)),
  });
  s.frames[1].cels[3][5] = 9;
  return s;
}

describe('project serialization', () => {
  it('is lossless across a full round-trip', () => {
    const original = richState();
    const text = serializeProject(original);
    const restored = deserializeProject(text);
    expect(restored).toEqual(original);
  });

  it('tags the file with the format name and version', () => {
    const dto = JSON.parse(serializeProject(createInitialState()));
    expect(dto.format).toBe(PROJECT_FORMAT);
    expect(dto.version).toBe(1);
  });

  it('preserves palette, layer order, frame order and durations', () => {
    const original = richState();
    const r = deserializeProject(serializeProject(original));
    expect(r.palette).toEqual(original.palette);
    expect(r.layers.map((l) => l.name)).toEqual(original.layers.map((l) => l.name));
    expect(r.layers.map((l) => l.opacity)).toEqual(original.layers.map((l) => l.opacity));
    expect(r.frames.map((f) => f.duration)).toEqual([7, 3]);
    expect(r.frames[1].cels[3][5]).toBe(9);
  });

  it('preserves tool settings', () => {
    const r = deserializeProject(serializeProject(richState()));
    expect(r.tool).toBe('rect');
    expect(r.brushSize).toBe(2);
    expect(r.activeColor).toBe(6);
    expect(r.fps).toBe(12);
    expect(r.loop).toBe(false);
    expect(r.onionSkin).toBe(true);
    expect(r.onionOpacity).toBe(55);
  });

  it('rejects non-project and malformed input', () => {
    expect(() => deserializeProject('not json')).toThrow();
    expect(() => deserializeProject(JSON.stringify({ hello: 1 }))).toThrow(/spriteforge/i);
    expect(() =>
      deserializeProject(JSON.stringify({ format: 'spriteforge', version: 99, doc: {} }))
    ).toThrow(/version/i);
    expect(() =>
      deserializeProject(
        JSON.stringify({
          format: 'spriteforge',
          version: 1,
          doc: { width: 2, height: 2, palette: ['#000000'], layers: [], frames: [] },
        })
      )
    ).toThrow();
  });

  it('rejects cels that reference a missing palette index', () => {
    const bad = {
      format: PROJECT_FORMAT,
      version: 1,
      doc: {
        width: 2,
        height: 2,
        palette: ['#000000'],
        layers: [{ id: 'a', name: 'L', visible: true, opacity: 100 }],
        frames: [{ duration: 4, cels: [{ rle: '5:4' }] }], // index 5 not in palette
        activeFrame: 0,
        activeLayer: 0,
        fps: 8,
        loop: true,
        onionSkin: false,
        onionOpacity: 30,
        tool: 'pencil',
        brushSize: 1,
      },
    };
    expect(() => deserializeProject(JSON.stringify(bad))).toThrow(/palette/i);
  });
});

import { describe, it, expect } from 'vitest';
import { computeSpritesheetLayout, buildSpritesheet } from './spritesheet';
import { blankRGBA } from '../model/composite';
import type { RGBA } from '../model/composite';

function solid(w: number, h: number, r: number, g: number, b: number): RGBA {
  const o = blankRGBA(w, h);
  for (let p = 0; p < w * h; p++) {
    o.data[p * 4] = r;
    o.data[p * 4 + 1] = g;
    o.data[p * 4 + 2] = b;
    o.data[p * 4 + 3] = 255;
  }
  return o;
}

describe('spritesheet layout', () => {
  it('computes a uniform-gutter grid', () => {
    const l = computeSpritesheetLayout(4, 32, 32, 2, 1);
    expect(l.cols).toBe(2);
    expect(l.rows).toBe(2);
    expect(l.width).toBe(2 * 32 + 3 * 1);
    expect(l.height).toBe(2 * 32 + 3 * 1);
    expect(l.positions[0]).toEqual({ x: 1, y: 1 });
    expect(l.positions[1]).toEqual({ x: 34, y: 1 });
    expect(l.positions[2]).toEqual({ x: 1, y: 34 });
  });

  it('single row when cols == frameCount and zero padding', () => {
    const l = computeSpritesheetLayout(3, 32, 32, 3, 0);
    expect(l.width).toBe(96);
    expect(l.height).toBe(32);
    expect(l.positions[2]).toEqual({ x: 64, y: 0 });
  });
});

describe('buildSpritesheet', () => {
  it('blits frames into their cells and leaves padding transparent', () => {
    const frames = [solid(2, 2, 255, 0, 0), solid(2, 2, 0, 255, 0), solid(2, 2, 0, 0, 255)];
    const sheet = buildSpritesheet(frames, 3, 1);
    // cols=3, rows=1 -> width 3*2+4*1=10, height 1*2+2*1=4
    expect(sheet.width).toBe(10);
    expect(sheet.height).toBe(4);
    const at = (x: number, y: number) => {
      const o = (y * sheet.width + x) * 4;
      return [sheet.data[o], sheet.data[o + 1], sheet.data[o + 2], sheet.data[o + 3]];
    };
    expect(at(1, 1)).toEqual([255, 0, 0, 255]); // frame0
    expect(at(4, 1)).toEqual([0, 255, 0, 255]); // frame1 (x=4)
    expect(at(7, 1)).toEqual([0, 0, 255, 255]); // frame2 (x=7)
    expect(at(0, 0)[3]).toBe(0); // padding transparent
  });
});

import { describe, it, expect } from 'vitest';
import { encodeGif } from './gif';
import { blankRGBA } from '../model/composite';
import type { RGBA } from '../model/composite';

function solid(w: number, h: number, r: number, g: number, b: number, a = 255): RGBA {
  const o = blankRGBA(w, h);
  for (let p = 0; p < w * h; p++) {
    o.data[p * 4] = r;
    o.data[p * 4 + 1] = g;
    o.data[p * 4 + 2] = b;
    o.data[p * 4 + 3] = a;
  }
  return o;
}

const palette = ['#ff0000', '#00ff00', '#0000ff'];

describe('encodeGif', () => {
  it('produces a valid GIF byte stream', () => {
    const bytes = encodeGif(
      [
        { rgba: solid(4, 4, 255, 0, 0), duration: 4 },
        { rgba: solid(4, 4, 0, 255, 0), duration: 8 },
      ],
      { palette, fps: 8, loop: true }
    );
    expect(bytes).toBeInstanceOf(Uint8Array);
    const header = String.fromCharCode(...bytes.slice(0, 6));
    expect(header).toMatch(/^GIF8/);
    // Trailer byte.
    expect(bytes[bytes.length - 1]).toBe(0x3b);
  });

  it('is larger when durations/frames increase', () => {
    const a = encodeGif([{ rgba: solid(4, 4, 255, 0, 0), duration: 4 }], { palette, fps: 8, loop: true });
    const b = encodeGif(
      [
        { rgba: solid(4, 4, 255, 0, 0), duration: 4 },
        { rgba: solid(4, 4, 0, 255, 0), duration: 4 },
        { rgba: solid(4, 4, 0, 0, 255), duration: 4 },
      ],
      { palette, fps: 8, loop: true }
    );
    expect(b.length).toBeGreaterThan(a.length);
  });

  it('maps fully transparent pixels to the reserved index without throwing', () => {
    const bytes = encodeGif([{ rgba: solid(2, 2, 0, 0, 0, 0), duration: 1 }], { palette, fps: 8, loop: false });
    expect(bytes.length).toBeGreaterThan(0);
  });

  it('rejects empty input', () => {
    expect(() => encodeGif([], { palette, fps: 8, loop: true })).toThrow();
  });
});

import { describe, it, expect } from 'vitest';
import { resampleNearest, quantizeRgbaToCel } from './import';
import { blankRGBA } from '../model/composite';

describe('resampleNearest', () => {
  it('returns a copy at the same size', () => {
    const src = blankRGBA(4, 4);
    src.data[0] = 123;
    const out = resampleNearest(src, 4, 4);
    expect(out.data[0]).toBe(123);
    expect(out.data).not.toBe(src.data);
  });

  it('downscales by sampling the top-left of each destination cell', () => {
    const src = blankRGBA(4, 4);
    // Mark (2,2) red so that the (1,1) dst cell picks it up.
    const o = (2 * 4 + 2) * 4;
    src.data[o] = 255;
    src.data[o + 3] = 255;
    const out = resampleNearest(src, 2, 2);
    expect(out.width).toBe(2);
    expect(out.height).toBe(2);
    expect(out.data[(1 * 2 + 1) * 4]).toBe(255);
  });
});

describe('quantizeRgbaToCel', () => {
  it('maps colors to the nearest palette index and keeps transparency', () => {
    const rgba = blankRGBA(2, 1);
    rgba.data[0] = 240;
    rgba.data[1] = 10;
    rgba.data[2] = 10;
    rgba.data[3] = 255; // pixel0: near red
    rgba.data[4 + 3] = 0; // pixel1: transparent
    const cel = quantizeRgbaToCel(rgba, ['#000000', '#ff0000', '#00ff00']);
    expect(cel[0]).toBe(1);
    expect(cel[1]).toBe(-1);
  });
});

