:root {
  --bg: #14151a;
  --panel: #1e2028;
  --panel-2: #262935;
  --border: #333744;
  --text: #d7d9e0;
  --muted: #8b8f9e;
  --accent: #6f98bd;
  --accent-2: #73eff7;
  --danger: #e43b44;
  --radius: 8px;
  font-synthesis: none;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--bg);
  color: var(--text);
  font: 13px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
}

button {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 9px;
  font-size: 12px;
  cursor: pointer;
}

button:hover {
  border-color: var(--accent);
}

button:active {
  transform: translateY(1px);
}

button[disabled] {
  opacity: 0.4;
  cursor: default;
}

select,
input[type="number"],
input[type="color"] {
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 3px 5px;
  font-size: 12px;
}

input[type="number"] {
  width: 52px;
}

kbd,
.kbd {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  color: var(--muted);
}

/* ---- top bar -------------------------------------------------------- */

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  height: 46px;
  padding: 0 12px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}

.brand {
  font-weight: 700;
  letter-spacing: 0.3px;
  white-space: nowrap;
}

.logo {
  color: var(--accent-2);
}

.file-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.file-actions .sep {
  width: 1px;
  height: 20px;
  background: var(--border);
  margin: 0 2px;
}

.status {
  margin-left: auto;
  color: var(--muted);
  min-width: 120px;
  text-align: right;
  white-space: nowrap;
}

/* ---- layout --------------------------------------------------------- */

.layout {
  display: grid;
  grid-template-columns: 1fr 300px;
  grid-template-rows: 1fr auto;
  grid-template-areas:
    "canvas sidebar"
    "film sidebar";
  height: calc(100vh - 46px);
}

.canvas-area {
  grid-area: canvas;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px;
  overflow: auto;
  outline: none;
}

.canvas-area:focus-visible {
  box-shadow: inset 0 0 0 2px var(--accent);
}

#canvas {
  width: 512px;
  height: 512px;
  max-width: 100%;
  max-height: calc(100vh - 220px);
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #000;
  border: 1px solid var(--border);
  border-radius: 4px;
  cursor: crosshair;
  touch-action: none;
}

.canvas-hint {
  color: var(--muted);
  font-size: 11px;
}

.filmstrip-area {
  grid-area: film;
  background: var(--panel);
  border-top: 1px solid var(--border);
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 150px;
}

.playback {
  display: flex;
  align-items: center;
  gap: 6px;
}

.playback button {
  width: 30px;
  height: 26px;
}

.mini {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  font-size: 11px;
}

.frame-readout {
  margin-left: auto;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.filmstrip {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 6px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  min-height: 60px;
}

.thumb {
  position: relative;
  flex: 0 0 auto;
  border: 2px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  background: #000;
}

.thumb canvas {
  display: block;
  image-rendering: pixelated;
}

.thumb.active {
  border-color: var(--accent-2);
}

.thumb .idx {
  position: absolute;
  left: 2px;
  bottom: 1px;
  font-size: 9px;
  color: #fff;
  background: rgba(0, 0, 0, 0.6);
  padding: 0 3px;
  border-radius: 3px;
}

.thumb .dur {
  position: absolute;
  right: 2px;
  bottom: 1px;
  font-size: 9px;
  color: var(--accent-2);
  background: rgba(0, 0, 0, 0.6);
  padding: 0 3px;
  border-radius: 3px;
}

.filmstrip-tools {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

/* ---- sidebar -------------------------------------------------------- */

.sidebar {
  grid-area: sidebar;
  background: var(--panel);
  border-left: 1px solid var(--border);
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.panel {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px;
}

.panel h3 {
  margin: 0 0 8px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  display: flex;
  justify-content: space-between;
}

.row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  flex-wrap: wrap;
}

.row > span {
  color: var(--muted);
  font-size: 11px;
}

.seg {
  display: inline-flex;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
}

.seg button {
  border: none;
  border-radius: 0;
}

.seg button.active {
  background: var(--accent);
  color: #04121c;
}

.tools {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.tool {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 6px 2px;
  font-size: 11px;
}

.tool .g {
  font-size: 15px;
}

.tool.active {
  background: var(--accent);
  color: #04121c;
  border-color: var(--accent-2);
}

.palette-current {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.active-swatch {
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: repeating-conic-gradient(#808080 0% 25%, #c0c0c0 0% 50%) 0 / 10px 10px;
  position: relative;
}

.active-swatch .fill {
  position: absolute;
  inset: 0;
  border-radius: 5px;
}

.palette-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 4px;
}

.swatch {
  aspect-ratio: 1;
  border-radius: 4px;
  border: 1px solid var(--border);
  cursor: pointer;
  position: relative;
}

.swatch.active {
  outline: 2px solid var(--accent-2);
  outline-offset: 1px;
}

.layers {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 220px;
  overflow-y: auto;
}

.layer {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 6px;
  cursor: pointer;
}

.layer.active {
  border-color: var(--accent-2);
  background: #23303f;
}

.layer .vis {
  width: 18px;
  text-align: center;
  cursor: pointer;
}

.layer .name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.layer input.opacity {
  width: 54px;
}

