() => {
  // Reach the app via DOM effects only: check undo button enabled after drawing,
  // and inspect canvas pixels for a non-transparent, non-checker painted pixel.
  const c = document.getElementById('canvas');
  const ctx = c.getContext('2d');
  const { data } = ctx.getImageData(0, 0, c.width, c.height);
  // count pixels matching active color #000000 that are fully opaque solid black
  let blacks = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i] === 0 && data[i+1] === 0 && data[i+2] === 0 && data[i+3] === 255) blacks++;
  }
  return { undoDisabled: document.getElementById('btn-undo').disabled, blackPixels: blacks };
}

