async () => {
  const raf2 = () => new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
  const status = () => document.getElementById('status').textContent;
  const grid = () => Array.from(document.getElementById('palette-grid').children).map(c => c.style.background);
  const results = {};

  // palette reorder
  const before = grid();
  document.getElementById('btn-palette-right').click();
  await raf2();
  const after = grid();
  results.paletteMovedRight = JSON.stringify(before) !== JSON.stringify(after);
  results.before2 = before.slice(0,2);
  results.after2 = after.slice(0,2);

  // keyboard gate: 'g' with focus NOT on canvas
  document.getElementById('btn-palette-right').focus();
  results.focusBefore = document.activeElement?.id;
  const t0 = status();
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'g', bubbles: true }));
  await raf2();
  results.gatedCorrectly = status() === t0;

  // keyboard works with canvas focus -> 'l'
  document.getElementById('canvas-area').focus();
  results.focusNow = document.activeElement?.id;
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'l', bubbles: true }));
  await raf2();
  results.toolWithFocus = status();

  return results;
}

