  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b', bubbles: true })); // pencil
  await raf2();
  const framesBefore = status();
  document.getElementById('btn-frame-add').click(); // history push (tool=pencil in snapshot)
  await raf2();
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'r', bubbles: true })); // switch to rect
  await raf2();
  const afterToolSwitch = status();
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'z', ctrlKey: true, bubbles: true })); // undo
  await raf2();
  const afterUndo = status();
  return { framesBefore, afterToolSwitch, afterUndo, toolPreserved: afterUndo.startsWith('rect') && framesBefore !== afterUndo };
}

