    e.preventDefault();
    playback.toggle();
    return;
  }
  if (k === 'arrowleft' || k === 'arrowright') {
    const s = doc.getState();
    const next = s.activeFrame + (k === 'arrowright' ? 1 : -1);
    if (next >= 0 && next < s.frames.length) {
      playback.stop();
      doc.setActiveFrame(next);
